#ifndef CONFIG_H
#define CONFIG_H
// Model dimensions come from model_config.h, generated by emg_common.export_hls together with the weights
// (install an export with scripts/install_export.py). This file adds the hardware settings and checks.
#include "model_config.h"

// Hardware parallelism: multiply-accumulates per cycle in each dense layer.
// Per encoder layer at 25 tokens and 100 MHz: about 4.7 ms with 4, 2.6 ms with 8 (scripts/estimate_cycles.py).
#ifndef MAC_UNROLL
#define MAC_UNROLL 4
#endif

#define NUM_OUTPUTS (OUT_DIM * (1 + HAS_DELTA_HEAD))   // [abs(10) | delta_std(10)]
#define IN_WORDS (IN_CHANNELS * RAW_SEQ_LEN)

// What this HLS implements: NUM_LAYERS post-norm encoder layers (attention + LayerNorm + FFN), mean pooling,
// absolute head (+ optional delta head). LayerNorm divides by D_MODEL with a shift (>> 7) and attention
// scales by 1/sqrt(HEAD_DIM) with a shift (>> 2), so those two dimensions are fixed.
#if D_MODEL != 128 || HEAD_DIM != 16 || NUM_HEADS * HEAD_DIM != D_MODEL || 2 * ROPE_HALF_DIM != D_MODEL
#error "HLS requires D_MODEL=128, HEAD_DIM=16 (8 heads)"
#endif
#if NUM_LAYERS < 1
#error "NUM_LAYERS must be >= 1"
#endif
#if (SEQ_LEN - 1) * CONV_STRIDE + KERNEL_SIZE - 2 * CONV_PADDING != RAW_SEQ_LEN
#error "SEQ_LEN, RAW_SEQ_LEN, KERNEL_SIZE and CONV_STRIDE are inconsistent"
#endif
#if (D_MODEL % MAC_UNROLL) || (D_FF % MAC_UNROLL) || (HEAD_DIM % MAC_UNROLL && MAC_UNROLL < HEAD_DIM)
#error "MAC_UNROLL must divide D_MODEL, D_FF and HEAD_DIM"
#endif
#endif // CONFIG_H
